DROP TABLE IF EXISTS `auditoria`;
CREATE TABLE `auditoria` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `usuario_id` int(11) unsigned DEFAULT NULL,
  `usuario_nombre` varchar(255) NOT NULL,
  `accion` varchar(50) NOT NULL COMMENT 'CREAR, EDITAR, ELIMINAR, LOGIN, LOGOUT, etc.',
  `modulo` varchar(100) NOT NULL COMMENT 'Bienes, Movimientos, Usuarios, etc.',
  `registro_id` int(11) unsigned DEFAULT NULL COMMENT 'ID del registro afectado',
  `detalles` text DEFAULT NULL COMMENT 'JSON o texto con detalles adicionales',
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `usuario_id` (`usuario_id`),
  KEY `modulo` (`modulo`),
  KEY `accion` (`accion`),
  KEY `created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


