DROP TABLE IF EXISTS `ips`;
CREATE TABLE `ips` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `direccion_ip` varchar(15) NOT NULL,
  `estado` enum('disponible','asignado','reservado') NOT NULL DEFAULT 'disponible',
  `id_persona` int(5) unsigned DEFAULT NULL COMMENT 'FK a personas.id',
  `id_departamento` int(5) unsigned DEFAULT NULL COMMENT 'FK a departamentos.id',
  `piso` varchar(50) DEFAULT NULL,
  `bien_id` int(5) unsigned DEFAULT NULL COMMENT 'FK a bienes.id',
  `observaciones` text DEFAULT NULL,
  `fecha_asignacion` date DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `direccion_ip` (`direccion_ip`),
  KEY `fk_ips_personas` (`id_persona`),
  KEY `fk_ips_departamentos` (`id_departamento`),
  KEY `fk_ips_bienes` (`bien_id`),
  CONSTRAINT `fk_ips_bienes` FOREIGN KEY (`bien_id`) REFERENCES `bienes` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ips_departamentos` FOREIGN KEY (`id_departamento`) REFERENCES `departamentos` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ips_personas` FOREIGN KEY (`id_persona`) REFERENCES `personas` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `licencias`;
CREATE TABLE `licencias` (
